CREATE OR REPLACE FUNCTION public.record_asaas_webhook_event(p_event_id text, p_event_type text, p_payload jsonb) RETURNS TABLE(log_id uuid, processing_status text, newly_recorded boolean) LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF p_event_id IS NULL OR length(p_event_id) NOT BETWEEN 2 AND 120 OR p_event_type IS NULL OR length(p_event_type) NOT BETWEEN 2 AND 120 THEN RAISE EXCEPTION 'Invalid Asaas event identity'; END IF; INSERT INTO public.webhook_logs (provider, webhook_id, event_type, origem, status, payload, attempts) VALUES ('asaas', p_event_id, p_event_type, 'asaas', 'received', p_payload, 0) ON CONFLICT (provider,webhook_id) WHERE provider IS NOT NULL AND webhook_id IS NOT NULL DO NOTHING RETURNING id, status INTO log_id,processing_status; newly_recorded := log_id IS NOT NULL; IF NOT newly_recorded THEN SELECT id,status INTO log_id,processing_status FROM public.webhook_logs WHERE provider='asaas' AND webhook_id=p_event_id; END IF; RETURN NEXT; END; $$; REVOKE ALL ON FUNCTION public.record_asaas_webhook_event(text,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.record_asaas_webhook_event(text,text,jsonb) TO service_role;